const directions=[
{id:'proof',number:'01',name:'业务证明',headline:'94% 的客户选择继续使用，因为节省效果每个月都看得见',memory:'这家公司已经获得客户持续认可，现在准备复制增长。',support:'18 家签约工厂、32MWh 在运容量、过去 12 个月收入 3,600 万元。',need:'如果能提供续约具体对应的软件或服务，这条故事会更完整。',storyTitle:'围绕“客户持续认可”展开',reason:'先用续约率和收入建立可信度，再解释产品为什么能持续创造价值。',missing:'94% 的客户具体续约了什么？如果暂时无法提供，我们会只使用“客户持续合作”的稳妥表述。',order:['opening','traction','problem','product','model','market','team','ask']},
{id:'speed',number:'02',name:'速度重构',headline:'六周内，让能源改造开始证明回报',memory:'他们把一项漫长的工程项目，变成了可以快速验证的经营决策。',support:'标准化储能柜、预测软件和团队 120+ 项目的交付经验。',need:'行业通常需要多久完成部署？这个对比能放大“六周”的价值。',storyTitle:'围绕“六周验证回报”展开',reason:'先用交付速度制造兴趣，再用续约率和收入证明这不是一次性的工程能力。',missing:'行业通常需要多久完成部署？如果暂时无法提供，我们会用现有的六周事实继续生成。',order:['opening','speed','traction','problem','product','model','market','team','ask']},
{id:'software',number:'03',name:'软件增长',headline:'硬件完成部署，软件持续证明每一笔能源投资的价值',memory:'这家公司用硬件进入工厂，再通过软件形成持续收入。',support:'能耗预测软件、按月展示节省、94% 客户续约率。',need:'目前还缺软件收入占比或实际使用频率，但不影响先生成这版故事。',storyTitle:'围绕“持续软件价值”展开',reason:'先把公司从工程项目中区分出来，再用客户续约证明软件价值可以持续。',missing:'软件收入占比是多少？如果暂时无法提供，我们会避免强调收入结构，只讲持续价值。',order:['opening','software','traction','problem','product','model','market','team','ask']}
];
const beats={opening:{title:'一句话定位',note:'让投资人立刻知道客户与价值',time:'0:30'},speed:{title:'六周意味着什么',note:'把速度转化为客户可感知的价值',time:'1:10'},software:{title:'持续软件价值',note:'说明部署之后为什么还会持续付费',time:'1:10'},traction:{title:'业务已经发生',note:'用客户、收入和续约建立可信度',time:'1:20'},problem:{title:'客户原来的困境',note:'解释为什么现有做法不够好',time:'1:10'},product:{title:'产品如何做到',note:'只展开与主叙事有关的能力',time:'1:30'},model:{title:'增长如何形成',note:'连接收入、交付与复制方式',time:'1:10'},market:{title:'从哪里开始扩大',note:'明确客户范围和市场入口',time:'1:00'},team:{title:'为什么是这支团队',note:'用经历解释执行能力',time:'0:50'},ask:{title:'下一阶段',note:'说明资金将放大什么',time:'1:20'}};
const slideData={opening:{theme:'',label:'澄光能源',title:'让制造工厂更快看见能源投资的回报',body:'模块化储能系统，六周部署，持续展示真实节省'},speed:{theme:'yellow',label:'交付速度',title:'六周完成部署，回报验证随即开始',body:'标准化硬件减少现场改造，预测软件持续调整运行策略',metric:'6周'},software:{theme:'yellow',label:'持续价值',title:'软件让每个月的节省都可以被看见',body:'部署不是项目终点，而是持续优化和订阅关系的起点'},traction:{theme:'yellow',label:'业务进展',title:'客户已经用续约证明价值',body:'18 家签约工厂，32MWh 在运容量，过去 12 个月收入 3,600 万元',metric:'94%'},problem:{theme:'paper',label:'客户问题',title:'传统能源改造周期长，实际回报难以判断',body:'人工错峰不可持续，大型定制项目又需要长期投入'},product:{theme:'',label:'产品',title:'标准硬件负责执行，软件持续优化收益',body:'储能柜完成现场运行，预测软件决定何时充放电'},model:{theme:'paper',label:'增长方式',title:'用标准化交付覆盖更多高耗能工厂',body:'设备收入建立项目基础，持续服务扩大客户价值'},market:{theme:'',label:'市场切入',title:'先覆盖华东高耗能制造工厂',body:'从明确客户画像出发，再扩展区域与行业'},team:{theme:'paper',label:'团队',title:'120+ 项目经验形成交付优势',body:'团队来自宁德时代、远景能源和施耐德'},ask:{theme:'',label:'本轮计划',title:'2,000 万元扩大已验证的交付模式',body:'扩大华东交付团队，完成第二代认证，补充项目周转资金'}};
const state={step:0,unlocked:0,name:'澄光能源',selected:1,currentSlide:0,story:[]};
const scenes=[...document.querySelectorAll('.scene')],journey=[...document.querySelectorAll('.journey-step')],sourceText=document.querySelector('#sourceText'),fileInput=document.querySelector('#fileInput'),toast=document.querySelector('#toast');
function showToast(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1700)}
function goTo(step){if(step>state.unlocked)return;state.step=step;scenes.forEach((el,i)=>el.classList.toggle('active',i===step));journey.forEach((el,i)=>{el.classList.toggle('active',i===step);el.classList.toggle('done',i<step);el.disabled=i>state.unlocked});window.scrollTo({top:0,behavior:'smooth'})}
function unlock(step){state.unlocked=Math.max(state.unlocked,step);goTo(step)}
journey.forEach((button,index)=>button.addEventListener('click',()=>goTo(index)));document.querySelector('#homeButton').addEventListener('click',()=>goTo(0));
document.querySelector('#briefForm').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);state.name=data.get('name').trim()||'未命名项目';document.querySelector('#projectName').textContent=state.name;unlock(1)});
function updateChars(){document.querySelector('#charCount').textContent=`${sourceText.value.trim().length} 字`}sourceText.addEventListener('input',updateChars);updateChars();
document.querySelectorAll('.source-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.source-tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.source-panel').forEach(x=>x.classList.toggle('active',x.dataset.sourcePanel===tab.dataset.source))}));
document.querySelector('#uploadButton').addEventListener('click',()=>fileInput.click());fileInput.addEventListener('change',()=>{document.querySelector('#fileList').innerHTML=[...fileInput.files].map(file=>`<li>${file.name} · ${Math.ceil(file.size/1024)} KB</li>`).join('')});
function renderDirections(){document.querySelector('#directionNav').innerHTML=directions.map((d,i)=>`<button class="direction-tab${i===state.selected?' active':''}" type="button" data-direction="${i}"><b>${d.number}</b>${d.name}</button>`).join('');const d=directions[state.selected];document.querySelector('#reframeStage').innerHTML=`<p class="reframe-kicker">创意总监的重述</p><h2>${d.headline}</h2><div class="reframe-detail"><div><h3>听众会记住</h3><p>${d.memory}</p></div><div class="need"><h3>还可以补强，但不强制</h3><p>${d.need}</p></div><div><h3>现有素材如何支撑</h3><p>${d.support}</p></div></div>`}
document.querySelector('#directionNav').addEventListener('click',event=>{const button=event.target.closest('[data-direction]');if(!button)return;state.selected=Number(button.dataset.direction);renderDirections()});
document.querySelector('#analyzeButton').addEventListener('click',()=>{if(sourceText.value.trim().length<40&&!fileInput.files.length)return showToast('至少提供一段公司材料');const overlay=document.querySelector('#analysisOverlay'),status=document.querySelector('#analysisStatus'),stages=['读取业务信息','寻找可以放大的亮点','生成三种主打方向'];overlay.classList.add('active');let i=0;const timer=setInterval(()=>status.textContent=stages[++i]||stages[2],420);setTimeout(()=>{clearInterval(timer);overlay.classList.remove('active');state.selected=1;renderDirections();unlock(2)},1450)});
function buildStory(){const d=directions[state.selected];state.story=d.order.map(key=>({...beats[key],key}));document.querySelector('#storyHeading').textContent=d.storyTitle;document.querySelector('#storyReason').textContent=d.reason;document.querySelector('#missingPrompt').textContent=d.missing;renderStory()}
document.querySelector('#chooseDirection').addEventListener('click',()=>{buildStory();unlock(3)});
function renderStory(){document.querySelector('#storyline').innerHTML=state.story.map((beat,index)=>`<article class="beat" data-index="${index}"><span class="beat-index">${index+1}</span><div><h3>${beat.title}</h3><p>${beat.note}</p></div><span class="beat-time">${beat.time}</span><div class="beat-actions"><button type="button" data-move="up" aria-label="上移">↑</button><button type="button" data-move="down" aria-label="下移">↓</button></div></article>`).join('')}
document.querySelector('#storyline').addEventListener('click',event=>{const button=event.target.closest('[data-move]');if(!button)return;const index=Number(button.closest('.beat').dataset.index),next=button.dataset.move==='up'?index-1:index+1;if(next<0||next>=state.story.length)return;[state.story[index],state.story[next]]=[state.story[next],state.story[index]];renderStory()});
document.querySelector('#skipMissing').addEventListener('click',()=>showToast('已接受信息缺失，继续使用现有素材'));
function renderDeck(){const deck=state.story.map(item=>slideData[item.key]).filter(Boolean),item=deck[state.currentSlide];document.querySelector('#deckTitle').textContent=state.name;document.querySelector('#deckThumbs').innerHTML=deck.map((slide,index)=>`<button class="deck-thumb${index===state.currentSlide?' active':''}" type="button" data-slide="${index}"><span>${String(index+1).padStart(2,'0')}</span>${slide.label}</button>`).join('');const slide=document.querySelector('#slide');slide.className=`slide ${item.theme}`;slide.innerHTML=`<div class="slide-inner"><span class="slide-label">${item.label}</span>${item.metric?`<strong class="metric">${item.metric}</strong>`:''}<h2>${item.title}</h2><p>${item.body}</p></div>`;document.querySelector('#speakerNote').textContent=`这一页只完成一个任务：${state.story[state.currentSlide].note}。`;document.querySelector('#slideCount').textContent=`${state.currentSlide+1} / ${deck.length}`}
document.querySelector('#buildDeckButton').addEventListener('click',()=>{state.currentSlide=0;unlock(4);renderDeck()});document.querySelector('#deckThumbs').addEventListener('click',event=>{const button=event.target.closest('[data-slide]');if(!button)return;state.currentSlide=Number(button.dataset.slide);renderDeck()});document.querySelector('#prevSlide').addEventListener('click',()=>{const n=state.story.length;state.currentSlide=(state.currentSlide-1+n)%n;renderDeck()});document.querySelector('#nextSlide').addEventListener('click',()=>{const n=state.story.length;state.currentSlide=(state.currentSlide+1)%n;renderDeck()});document.querySelector('#backToStory').addEventListener('click',()=>goTo(3));
document.querySelector('#sampleButton').addEventListener('click',()=>{state.name='澄光能源';document.querySelector('#projectName').textContent=state.name;document.querySelector('#briefForm [name="name"]').value=state.name;state.unlocked=2;state.selected=1;renderDirections();goTo(2);showToast('直接比较三种主打方向')});
